def equi_leaders(nums):
    leader, count = None, 0
    for x in nums:
        if count == 0:
            leader = x
        count += 1 if x == leader else -1
    n = len(nums)
    total = sum(1 for x in nums if x == leader)
    if total * 2 <= n:
        return 0
    splits, left = 0, 0
    for i in range(n - 1):
        if nums[i] == leader:
            left += 1
        right = total - left
        if left * 2 > i + 1 and right * 2 > n - i - 1:
            splits += 1
    return splits

