int equiLeaders(const int* nums, int n) {
    int leader = 0, count = 0;
    for (int i = 0; i < n; i++) {
        if (count == 0) leader = nums[i];
        count += nums[i] == leader ? 1 : -1;
    }
    int total = 0;
    for (int i = 0; i < n; i++) if (nums[i] == leader) total++;
    if (total * 2 <= n) return 0;
    int splits = 0, left = 0;
    for (int i = 0; i < n - 1; i++) {
        if (nums[i] == leader) left++;
        int right = total - left;
        if (left * 2 > i + 1 && right * 2 > n - i - 1) splits++;
    }
    return splits;
}
